from itertools import permutations

people = ['Alice','Bob','Charlie','David','Ethan','Frankie']
n=6

def solve(right_dir):
    # right_dir: +1 means 'right' = increasing index mod n, left = decreasing
    results = []
    for perm in permutations(people):
        pos = {name: i for i, name in enumerate(perm)}
        def adjacent(a,b):
            return (pos[a]-pos[b]) % n in (1, n-1)
        def right_of(a, k):
            return (pos[a] + right_dir*k) % n
        def left_of(a, k):
            return (pos[a] - right_dir*k) % n
        def across(a):
            return (pos[a] + n//2) % n

        # Bob two seats to the left of Alice
        if pos['Bob'] != left_of('Alice', 2):
            continue
        # Bob refuses to sit next to Ethan
        if adjacent('Bob','Ethan'):
            continue
        # If Ethan across from Bob then David two seats to the right of Alice
        if pos['Ethan'] == across('Bob'):
            if pos['David'] != right_of('Alice', 2):
                continue
        # Alice and Frankie rivals -> not adjacent
        if adjacent('Alice','Frankie'):
            continue
        # Frankie must sit next to David or Ethan
        if not (adjacent('Frankie','David') or adjacent('Frankie','Ethan')):
            continue
        results.append(perm)
    return results

for right_dir in (1,-1):
    res = solve(right_dir)
    pairs = set()
    for perm in res:
        pos = {name:i for i,name in enumerate(perm)}
        neighbors = (perm[(pos['Charlie']-1)%n], perm[(pos['Charlie']+1)%n])
        pairs.add(tuple(sorted(neighbors)))
    print('right_dir=',right_dir,'num arrangements (rotations counted separately since we fix nothing):', len(res))
    print('Charlie neighbor pairs:', pairs)
"
